using System; using System.Linq; using Microsoft.AspNetCore.Identity.EntityFrameworkCore; using Microsoft.EntityFrameworkCore; using Microsoft.AspNetCore.Identity; class AppUser : IdentityUser {} class Ctx : IdentityDbContext<AppUser> { public Ctx(DbContextOptions<Ctx> o) : base(o) {} protected override void OnModelCreating(ModelBuilder b) { base.OnModelCreating(b); foreach(var item in b.Model.GetEntityTypes().Where(e => !e.IsOwned() && e.ClrType != typeof(IdentityPasskeyData)).ToList()) { var props = item.ClrType?.GetProperties().Where(p => p.PropertyType == typeof(DateTimeOffset)); if (props != null && props.Any()) { foreach(var p in props) { b.Entity(item.ClrType).Property(p.Name); } } } } } class Program { static void Main() { var b = new DbContextOptionsBuilder<Ctx>(); b.UseSqlite("DataSource=:memory:"); var c = new Ctx(b.Options); try { c.Database.EnsureCreated(); Console.WriteLine("SUCCESS!"); } catch(Exception ex) { Console.WriteLine("ERR: " + ex.Message); } } }
